<!doctype html>
<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Paket yönetimi</title><link rel="stylesheet" href="/assets/app.css"></head>
<body><main class="container"><h1>Paket yönetimi</h1><p><a href="/admin">Yönetim paneli</a></p><?php if(!empty($_SESSION['success'])): ?><p class="success"><?= e($_SESSION['success']) ?></p><?php unset($_SESSION['success']); endif; ?><?php if(!empty($_SESSION['error'])): ?><p class="alert"><?= e($_SESSION['error']) ?></p><?php unset($_SESSION['error']); endif; ?>
<h2>Yeni paket</h2><form method="post" action="/admin/plans/store"><?= csrf_field() ?><label>Ad</label><input name="name" required><label>Slug</label><input name="slug" required><label>Açıklama</label><textarea name="description"></textarea><label>Fiyat</label><input type="number" name="price" min="0" step="0.01" required><label>Para birimi</label><input name="currency" value="TRY" maxlength="3" required><label>Dönem</label><select name="billing_period"><option value="monthly">Aylık</option><option value="yearly">Yıllık</option></select><label>Günlük ziyaret limiti</label><input type="number" name="daily_visit_limit" min="1" required><label>Site limiti</label><input type="number" name="website_limit" min="1" required><label>Özellikler (her satıra bir özellik)</label><textarea name="features"></textarea><label>Sıralama</label><input type="number" name="sort_order" value="0"><label><input type="checkbox" name="is_active" checked> Aktif</label><button type="submit">Oluştur</button></form>
<h2>Mevcut paketler</h2><?php foreach($plans as $plan): $features=json_decode((string)($plan['features']??'[]'),true) ?: []; ?><section class="site-card"><form method="post" action="/admin/plans/update"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$plan['id'] ?>"><label>Ad</label><input name="name" value="<?= e($plan['name']) ?>" required><label>Slug</label><input name="slug" value="<?= e($plan['slug']) ?>" required><label>Açıklama</label><textarea name="description"><?= e($plan['description']) ?></textarea><label>Fiyat</label><input type="number" name="price" min="0" step="0.01" value="<?= e($plan['price']) ?>" required><label>Para birimi</label><input name="currency" value="<?= e($plan['currency']) ?>" maxlength="3"><label>Dönem</label><select name="billing_period"><option value="monthly" <?= $plan['billing_period']==='monthly'?'selected':'' ?>>Aylık</option><option value="yearly" <?= $plan['billing_period']==='yearly'?'selected':'' ?>>Yıllık</option></select><label>Günlük ziyaret</label><input type="number" name="daily_visit_limit" min="1" value="<?= (int)$plan['daily_visit_limit'] ?>"><label>Site limiti</label><input type="number" name="website_limit" min="1" value="<?= (int)$plan['website_limit'] ?>"><label>Özellikler</label><textarea name="features"><?= e(implode("\n",is_array($features)?$features:[])) ?></textarea><label>Sıralama</label><input type="number" name="sort_order" value="<?= (int)$plan['sort_order'] ?>"><label><input type="checkbox" name="is_active" <?= $plan['is_active']?'checked':'' ?>> Aktif</label><button type="submit">Güncelle</button></form><form method="post" action="/admin/plans/delete" onsubmit="return confirm('Paket silinsin mi?');"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$plan['id'] ?>"><button type="submit">Sil</button></form></section><?php endforeach; ?></main></body></html>
